<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref} from 'vue'
import {ElMessage} from 'element-plus'
import {get,post,http,errorMessage} from '@/api/client'
import {parseTestSet,TEST_SET_EXAMPLE} from '../../../../../evaluation/batch-format'
defineOptions({name:'admin-evaluations'})
interface Turn {id:string;batchId:string;split:string;turn:number;question:string;reply:string;status:string;error?:string;previewTruncated?:boolean;latencyMs:number}
interface Job {id:string;title:string;status:string;total:number;batchCount:number;completed:number;succeeded:number;failed:number;createdAt:string;error?:string;turns?:Turn[]}
const title=ref('校园导览测试'),format=ref<'json'|'csv'>('json'),split=ref<'test'|'validation'>('test'),data=ref(TEST_SET_EXAMPLE),modelId=ref(''),agentId=ref(''),bypassCache=ref(true),preference=ref<'cards'|'adaptive'|'text'>('adaptive'),busy=ref(false),loading=ref(false),jobs=ref<Job[]>([]),selected=ref<Job>(),models=ref<{id:string;name:string}[]>([]),agents=ref<{id:string;name:string}[]>([]),fileInput=ref<HTMLInputElement>(),loadError=ref('');let timer:ReturnType<typeof setInterval>|undefined,polling=false,selectionVersion=0
const parsed=computed(()=>{try{const batches=parseTestSet(data.value,format.value,split.value);return {total:batches.reduce((n,b)=>n+b.questions.length,0),batches:batches.length,error:''}}catch(e){return {total:0,batches:0,error:(e as Error).message}}})
const active=(job?:Job)=>!!job&&['QUEUED','RUNNING','CANCELLING'].includes(job.status)
const progress=computed(()=>selected.value?Math.round(selected.value.completed/selected.value.total*100):0)
const statuses:Record<string,string>={QUEUED:'排队中',RUNNING:'正在回复',CANCELLING:'正在停止',CANCELLED:'已停止',INTERRUPTED:'服务重启中断',COMPLETED:'已完成',FAILED:'失败',SUCCESS:'成功',PENDING:'待执行',SKIPPED:'前轮失败，已跳过'}
async function list(){loading.value=true;try{jobs.value=await get<Job[]>('/evaluations');loadError.value=''}catch(e){loadError.value=errorMessage(e)}finally{loading.value=false}}
async function select(id:string){const version=++selectionVersion;try{const detail=await get<Job>('/evaluations/'+id);if(version===selectionVersion){selected.value=detail;const index=jobs.value.findIndex(j=>j.id===id);if(index>=0)jobs.value[index]=detail}}catch(e){ElMessage.error(errorMessage(e))}}
async function create(){if(parsed.value.error||busy.value)return;busy.value=true;try{const job=await post<Job>('/evaluations',{title:title.value,format:format.value,split:split.value,data:data.value,modelId:modelId.value||undefined,agentId:agentId.value||undefined,bypassCache:bypassCache.value,outputPreference:preference.value});await list();await select(job.id);ElMessage.success('测试任务已提交，可以离开页面后再回来查看')}catch(e){ElMessage.error(errorMessage(e))}finally{busy.value=false}}
async function cancel(){if(!selected.value)return;busy.value=true;try{await post('/evaluations/'+selected.value.id+'/cancel');await select(selected.value.id)}catch(e){ElMessage.error(errorMessage(e))}finally{busy.value=false}}
async function download(kind:'json'|'csv'){if(!selected.value)return;try{const response=await http.get('/evaluations/'+selected.value.id+'/export',{params:{format:kind},responseType:'blob'}),url=URL.createObjectURL(response.data),link=document.createElement('a');link.href=url;link.download='evaluation-'+selected.value.id+'.'+kind;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){ElMessage.error(errorMessage(e))}}
async function importFile(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file)return;if(file.size>1_500_000){ElMessage.error('测试集文件最多 1.5MB');return}if(!/\.(json|csv)$/i.test(file.name)){ElMessage.error('请选择 JSON 或 CSV 文件');return}try{format.value=/\.csv$/i.test(file.name)?'csv':'json';data.value=await file.text();title.value=file.name.replace(/\.(json|csv)$/i,'').slice(0,120)}catch{ElMessage.error('文件读取失败，请重试')}}
function example(){data.value=format.value==='json'?TEST_SET_EXAMPLE:'batch_id,split,turn,question\n通勤-01,test,1,良乡校区附近的地铁站是哪个？\n通勤-01,test,2,怎么去？\n图书馆-01,validation,1,望京校区图书馆需要预约吗？'}
onMounted(async()=>{await Promise.allSettled([list(),get<{id:string;name:string}[]>('/models/available').then(v=>models.value=v),get<{id:string;name:string}[]>('/agents/available').then(v=>agents.value=v)]);if(jobs.value[0])await select(jobs.value[0].id);timer=setInterval(async()=>{if(polling||document.hidden||!active(selected.value))return;polling=true;try{await select(selected.value!.id)}finally{polling=false}},3000)})
onBeforeUnmount(()=>{if(timer)clearInterval(timer);selectionVersion++})
</script>
<template>
 <div class="evaluation-page">
  <header class="evaluation-header"><div><h1>批量对话测试</h1><p>导入测试集或验证集，让 Agent 按批次完成多轮回复，下载可核对的结果。</p></div><el-button @click="list" :loading="loading">刷新任务</el-button></header>
  <div class="evaluation-grid">
   <section class="evaluation-panel"><h2>准备测试集</h2><p class="evaluation-help">问题来自你上传的 JSON/CSV 或手动编辑。「载入示例」是代码内置的 3 道演示题，不是正式评测数据。测试集与验证集当前仅用于分类标记，不会训练模型或自动评分。</p><label for="evaluation-title">任务名称</label><el-input id="evaluation-title" v-model="title" maxlength="120" placeholder="输入任务名称"/>
    <div class="evaluation-fields"><div><label>文件格式</label><el-select v-model="format" aria-label="文件格式"><el-option label="JSON" value="json"/><el-option label="CSV" value="csv"/></el-select></div><div><label>默认数据集</label><el-select v-model="split" aria-label="默认数据集"><el-option label="测试集" value="test"/><el-option label="验证集" value="validation"/></el-select></div></div>
    <div class="evaluation-actions"><el-button @click="fileInput?.click()">导入文件</el-button><el-button @click="example">载入示例</el-button><span v-if="!parsed.error">{{parsed.batches}} 个批次 · {{parsed.total}} 道题</span></div><input ref="fileInput" type="file" accept=".json,.csv" class="evaluation-file" @change="importFile"/>
    <el-input v-model="data" type="textarea" :rows="10" aria-label="测试集内容" placeholder="粘贴 JSON 或 CSV 测试集"/><p v-if="parsed.error" class="evaluation-error" role="alert">{{parsed.error}}</p><p class="evaluation-help">相同批次按轮次保留上下文，不同批次独立。最多 500 题，每批最多 100 轮。CSV 列：batch_id、split、turn、question。</p>
    <div class="evaluation-fields"><div><label>模型</label><el-select v-model="modelId" clearable placeholder="使用默认模型" aria-label="测试模型"><el-option v-for="m in models" :key="m.id" :label="m.name" :value="m.id"/></el-select></div><div><label>智能体</label><el-select v-model="agentId" clearable placeholder="使用默认校园助手" aria-label="测试智能体"><el-option v-for="a in agents" :key="a.id" :label="a.name" :value="a.id"/></el-select></div></div>
    <label>输出偏好</label><el-select v-model="preference" aria-label="测试输出偏好"><el-option label="新式排版" value="adaptive"/><el-option label="固定卡片" value="cards"/><el-option label="文字为主" value="text"/></el-select><el-checkbox v-model="bypassCache">绕过回答缓存，测试实时生成</el-checkbox>
    <p class="evaluation-help">使用实际 Agent、知识检索与正常额度计费。测试不读写个人记忆，仅执行只读工具。每批前一轮失败时跳过后续追问；其他批次继续。</p><el-button type="primary" @click="create" :loading="busy" :disabled="!!parsed.error||!title.trim()">开始批量回复</el-button>
   </section>
   <section class="evaluation-panel"><h2>执行与结果</h2><p v-if="loadError" class="evaluation-error" role="alert">{{loadError}}</p><p v-if="!jobs.length&&!loading" class="evaluation-help">暂无任务，导入测试集后即可开始。</p><div class="evaluation-jobs"><button v-for="job in jobs" :key="job.id" class="evaluation-job" :class="{'is-selected':selected?.id===job.id}" @click="select(job.id)"><strong>{{job.title}}</strong><span>{{statuses[job.status]||job.status}} · {{job.completed}}/{{job.total}}</span></button></div>
    <template v-if="selected"><div class="evaluation-result-title"><h3>{{selected.title}}</h3><span>{{statuses[selected.status]||selected.status}}</span></div><el-progress :percentage="progress" :status="selected.status==='COMPLETED'?'success':undefined"/><div class="evaluation-metrics"><span>{{selected.batchCount}} 批次</span><span>成功 {{selected.succeeded}}</span><span>失败/跳过 {{selected.failed}}</span></div><p v-if="selected.error" class="evaluation-error">{{selected.error}}</p><div class="evaluation-actions"><el-button @click="download('json')">下载 JSON</el-button><el-button @click="download('csv')">下载 CSV</el-button><el-button v-if="active(selected)" @click="cancel" :disabled="busy||selected.status==='CANCELLING'">停止任务</el-button></div><p class="evaluation-help">可下载未完成任务的已有结果。预览仅展示每条回复前 4000 字，下载保留完整内容。</p>
     <div class="evaluation-turns"><article v-for="turn in selected.turns" :key="turn.id" class="evaluation-turn"><div class="evaluation-turn-meta"><span>{{turn.batchId}} · {{turn.split==='validation'?'验证集':'测试集'}} · 第 {{turn.turn}} 轮</span><span>{{statuses[turn.status]||turn.status}}</span></div><h4>{{turn.question}}</h4><p v-if="turn.error" class="evaluation-error">{{turn.error}}</p><pre v-if="turn.reply">{{turn.reply}}</pre><small v-if="turn.previewTruncated">完整回复请下载查看</small></article></div>
    </template>
   </section>
  </div>
 </div>
</template>
<style scoped>
.evaluation-page{padding:24px;max-width:1500px;margin:auto;color:var(--nx-text)}.evaluation-header{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:24px}.evaluation-header h1{font-size:26px;margin:0 0 8px}.evaluation-header p,.evaluation-help{color:var(--nx-text-3);line-height:1.7;font-size:13px}.evaluation-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.25fr);gap:20px;align-items:start}.evaluation-panel{border:1px solid var(--nx-border);border-radius:16px;padding:22px;background:var(--nx-surface);min-width:0}.evaluation-panel h2{font-size:18px;margin:0 0 20px}.evaluation-panel label{display:block;font-size:13px;margin:14px 0 8px;color:var(--nx-text-2)}.evaluation-panel .el-select{width:100%}.evaluation-panel .el-checkbox{display:flex;margin-top:16px}.evaluation-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.evaluation-actions,.evaluation-metrics{display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin:16px 0;font-size:12px;color:var(--nx-text-3)}.evaluation-actions .el-button+.el-button{margin-left:0}.evaluation-error{color:var(--nx-danger);font-size:13px;overflow-wrap:anywhere}.evaluation-file{display:none}.evaluation-jobs{display:grid;gap:8px;max-height:240px;overflow:auto}.evaluation-job{text-align:left;border:1px solid var(--nx-border);background:var(--nx-surface-2);color:var(--nx-text);border-radius:10px;padding:12px;cursor:pointer;display:flex;justify-content:space-between;gap:12px}.evaluation-job strong{overflow-wrap:anywhere}.evaluation-job span{flex-shrink:0;font-size:12px;color:var(--nx-text-3)}.evaluation-job.is-selected{border-color:var(--nx-accent)}.evaluation-result-title{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:20px 0;font-size:12px}.evaluation-result-title h3{margin:0;font-size:16px;overflow-wrap:anywhere}.evaluation-turns{max-height:800px;overflow:auto}.evaluation-turn{border-top:1px solid var(--nx-border);padding:18px 0}.evaluation-turn-meta{display:flex;justify-content:space-between;gap:10px;color:var(--nx-text-3);font-size:12px}.evaluation-turn h4{font-size:14px;line-height:1.6;overflow-wrap:anywhere;margin:12px 0}.evaluation-turn pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.75 inherit;margin:12px 0;color:var(--nx-text-2)}.evaluation-turn small{color:var(--nx-text-3)}@media(max-width:1000px){.evaluation-grid{grid-template-columns:1fr}.evaluation-page{padding:16px}.evaluation-header{align-items:flex-start}.evaluation-panel{padding:18px}.evaluation-job{flex-direction:column;gap:6px}}
</style>
